// ─────────────────────────────────────────────────────────────
// Merge form data (agency info) with each Apollo contact row.
// Maps exact Apollo CSV column names to clean field names.
// Returns MULTIPLE items — one per contact — for parallel
// processing through downstream nodes.
//
// Apollo CSV columns used:
//   First Name, Last Name, Title, Company Name, Email,
//   Email Status, # Employees, Industry, Keywords,
//   Person Linkedin Url, Website, City, State, Country,
//   Annual Revenue, Technologies, Seniority
// ─────────────────────────────────────────────────────────────
const contacts = $input.all();
const form = $('📋 Launch Campaign Form1').first().json;

const agencyName = form['Your Agency Name'] || '';
const service = form['Service You Are Selling'] || '';
const uvp = form['Your Unique Value Proposition'] || '';
const senderEmail = form['Your Sender Email'] || '';
const senderName = form['Your Full Name'] || '';

const leads = contacts
  .map((item, idx) => {
    const r = item.json;
    const email = (r['Email'] || '').trim();
    const emailStatus = (r['Email Status'] || '').trim();

    // Skip rows without verified email
    if (!email || emailStatus.toLowerCase() !== 'verified') return null;

    const firstName = (r['First Name'] || '').trim();
    const lastName = (r['Last Name'] || '').trim();
    const companyName = (r['Company Name'] || '').trim();
    const title = (r['Title'] || '').trim();
    const industry = (r['Industry'] || '').trim();
    const companySize = (r['# Employees'] || '').toString().trim();
    const keywords = (r['Keywords'] || '').trim();
    const website = (r['Website'] || '').trim();
    const linkedin = (r['Person Linkedin Url'] || '').trim();
    const city = (r['City'] || '').trim();
    const state = (r['State'] || '').trim();
    const country = (r['Country'] || '').trim();
    const revenue = (r['Annual Revenue'] || '').toString().trim();
    const tech = (r['Technologies'] || '').trim();
    const seniority = (r['Seniority'] || '').trim();

    // Build rich company context for AI personalization
    const companyContext = [
      industry ? `Industry: ${industry}` : '',
      companySize ? `${companySize} employees` : '',
      revenue ? `Revenue: ${revenue}` : '',
      keywords ? `Focus areas: ${keywords.slice(0, 150)}` : '',
      tech ? `Tech stack: ${tech.slice(0, 150)}` : '',
      website ? `Website: ${website}` : ''
    ].filter(Boolean).join('. ');

    return {
      leadIndex: idx + 1,
      firstName,
      lastName,
      fullName: `${firstName} ${lastName}`.trim(),
      email,
      title,
      seniority,
      companyName,
      companyIndustry: industry,
      companySize,
      companyKeywords: keywords,
      companyWebsite: website,
      companyRevenue: revenue,
      companyTech: tech,
      companyContext,
      linkedinUrl: linkedin,
      location: [city, state, country].filter(Boolean).join(', '),
      agencyName,
      service,
      uvp,
      senderEmail,
      senderName
    };
  })
  .filter(Boolean);

if (leads.length === 0) {
  throw new Error('No contacts with verified emails found in the Apollo Contacts sheet. Check that Email Status column says "Verified".');
}

return leads.map(l => ({ json: l }));

// ─────────────────────────────────────────────────────────────
// Build AI personalization prompt using the RICH Apollo data.
// Uses: company context, keywords, tech stack, revenue,
// seniority — far more personalized than basic name+company.
// ─────────────────────────────────────────────────────────────
const lead = $input.first().json;

const systemPrompt = `You are an expert cold email copywriter for ${lead.agencyName}. You write brutally short, hyper-personalized cold emails that get replies.

RULES:
- Reference something SPECIFIC about their company: their industry, tech stack, website, or business focus
- Under 100 words per email body
- No corporate jargon: never use "leverage", "synergy", "game-changer", "revolutionary", "cutting-edge"
- Sound like a helpful human, not a salesperson
- One soft call-to-action per email
- RESPOND ONLY with valid JSON. No markdown fences, no backticks, no extra text.`;

const userPrompt = `Write a 3-email cold outreach sequence for this prospect:

PROSPECT:
- Name: ${lead.fullName}
- Title: ${lead.title} (${lead.seniority})
- Company: ${lead.companyName}
- ${lead.companyContext}
- Location: ${lead.location}

SENDER:
- Name: ${lead.senderName} from ${lead.agencyName}
- Service: ${lead.service}
- Value proposition: ${lead.uvp}

Return EXACTLY this JSON:
{
  "email1_subject": "Curiosity-driving subject under 8 words",
  "email1_body": "Value-first intro. Reference their specific company/industry/tech. Under 100 words. End with soft CTA like 'Would a 15-min chat make sense this week?'",
  "email2_subject": "Follow-up subject under 8 words",
  "email2_body": "Social proof email. Mention a specific measurable result you achieved. Under 80 words.",
  "email3_subject": "Breakup subject under 8 words",
  "email3_body": "Friendly no-pressure farewell. Under 60 words. Often gets highest reply rate."
}`;

return [{ json: { ...lead, systemPrompt, userPrompt } }];

// ─────────────────────────────────────────────────────────────
// Parse AI-generated emails and merge with lead data.
// Includes fallback if AI returns malformed JSON.
// ─────────────────────────────────────────────────────────────
const aiResp = $input.first().json;
const lead = $input.first().json;
const { systemPrompt, userPrompt, ...cleanLead } = lead;

let emails = {};
try {
  const raw = aiResp?.message?.content || aiResp?.choices?.[0]?.message?.content || '{}';
  const cleaned = raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  emails = JSON.parse(cleaned);
} catch (e) {
  emails = {
    email1_subject: `Quick question about ${cleanLead.companyName}`,
    email1_body: `Hi ${cleanLead.firstName},\n\nI came across ${cleanLead.companyName} and noticed you're in the ${cleanLead.companyIndustry} space. I help companies like yours implement ${cleanLead.service}.\n\nWould a 15-minute chat make sense?\n\nBest,\n${cleanLead.senderName}`,
    email2_subject: `Following up \u2014 ${cleanLead.companyName}`,
    email2_body: `Hi ${cleanLead.firstName},\n\nJust circling back. We recently helped a similar ${cleanLead.companyIndustry} company achieve 40% better results with our AI solution.\n\nWorth a quick call?\n\n${cleanLead.senderName}`,
    email3_subject: `Closing the loop`,
    email3_body: `Hi ${cleanLead.firstName},\n\nI've reached out about AI automation for ${cleanLead.companyName}. If timing isn't right, totally understand.\n\nWishing ${cleanLead.companyName} all the best.\n\n${cleanLead.senderName}`
  };
}

const now = new Date();

return [{ json: {
  ...cleanLead,
  ...emails,
  dateGenerated: now.toLocaleDateString('en-IN', { year:'numeric', month:'short', day:'numeric' }),
  email1SentAt: now.toISOString(),
  status: 'Email 1 Sent'
}}];

// Capture Gmail threadId returned by the Send Email node
// and merge it with the lead data for CRM logging.
const gmailResult = $input.first().json;
const threadId = gmailResult.threadId || gmailResult.id || '';
return [{ json: { ...gmailResult, capturedThreadId: threadId } }];

// Reply Gate for Email 2
// output[0] = no reply → send Email 2
// output[1] = reply detected → mark replied, stop

const noReply = [];
const replied = [];

for (const item of $input.all()) {
  const messages = item.json?.messages ?? [];
  if (messages.length >= 2) {
    replied.push({ json: item.json });
  } else {
    noReply.push({ json: item.json });
  }
}

return [noReply, replied];

// Reply Gate for Email 3
// output[0] = no reply → send Email 3
// output[1] = reply detected → mark replied, stop

const noReply = [];
const replied = [];

for (const item of $input.all()) {
  const messages = item.json?.messages ?? [];
  if (messages.length >= 2) {
    replied.push({ json: item.json });
  } else {
    noReply.push({ json: item.json });
  }
}

return [noReply, replied];

// Only leads where 3+ days have passed since Email 1
const items = $input.all();
const now = Date.now();
const THREE_DAYS = 3 * 24 * 60 * 60 * 1000;

const due = items.filter(item => {
  const sentAt = item.json['Email 1 Sent At'];
  if (!sentAt) return false;
  return (now - new Date(sentAt).getTime()) >= THREE_DAYS;
});

if (due.length === 0) return [];
return due;

// Only leads where 4+ days have passed since Email 2
const items = $input.all();
const now = Date.now();
const FOUR_DAYS = 4 * 24 * 60 * 60 * 1000;

const due = items.filter(item => {
  const sentAt = item.json['Email 2 Sent At'];
  if (!sentAt) return false;
  return (now - new Date(sentAt).getTime()) >= FOUR_DAYS;
});

if (due.length === 0) return [];
return due;
